CREATE TABLE contact_message (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, company VARCHAR(160) NOT NULL, subject VARCHAR(100) NOT NULL, message VARCHAR(5000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE site_content (id BIGINT PRIMARY KEY, headline VARCHAR(100) NOT NULL, intro VARCHAR(500) NOT NULL, available BOOLEAN NOT NULL);
INSERT INTO site_content VALUES (1, 'Votre ambition. Notre code.', 'Nous transformons vos défis numériques en solutions utiles, solides et durables. Du premier conseil à la dernière ligne de code.', true);
